mapper.select:
SELECT c.courseid, c.coursename, c.teacherid, c.hours, c.description, c.semester, c.createtime, c.coursecode, t.teachername, (SELECT GROUP_CONCAT(ci.classname SEPARATOR ',') FROM courseclass cc LEFT JOIN classinfo ci ON cc.classid = ci.classid WHERE cc.courseid = c.courseid) as classNamesStr FROM course c LEFT JOIN teacher t ON c.teacherid = t.teacherid
AND c.coursename LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.courseid DESC LIMIT #{offset}, #{limit}

SELECT c.courseid, c.coursename, c.teacherid, c.hours, c.description, c.semester, c.createtime, c.coursecode, t.teachername, (SELECT GROUP_CONCAT(ci.classname SEPARATOR ',') FROM courseclass cc LEFT JOIN classinfo ci ON cc.classid = ci.classid WHERE cc.courseid = c.courseid) as classNamesStr FROM course c LEFT JOIN teacher t ON c.teacherid = t.teacherid WHERE c.teacherid = #{teacherid}
AND (c.semester = #{semester} OR c.semester LIKE CONCAT(#{semester}, '-%'))
AND c.semester = #{semester}
ORDER BY c.courseid DESC

SELECT c.courseid, c.coursename, c.teacherid, c.hours, c.description, c.semester, c.createtime, c.coursecode, t.teachername FROM course c LEFT JOIN teacher t ON c.teacherid = t.teacherid INNER JOIN courseclass cc ON c.courseid = cc.courseid WHERE cc.classid = #{classid}
AND (c.semester = #{semester} OR c.semester LIKE CONCAT(#{semester}, '-%'))
AND c.semester = #{semester}
ORDER BY c.courseid DESC

SELECT c.courseid, c.coursename, c.teacherid, c.hours, c.description, c.semester, c.createtime, c.coursecode
FROM course c
WHERE c.coursecode = #{coursecode}

mapper.update:
UPDATE course
SET coursename = #{coursename}, teacherid = #{teacherid}, hours = #{hours}, description = #{description}, coursecode = #{coursecode}, semester = #{semester}
WHERE courseid = #{courseid}
